package com.nexora.reports.support;

import com.nexora.reports.plan.domain.StoredPlan;
import com.nexora.reports.plan.infrastructure.PlanDocumentReader;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;
import tools.jackson.databind.node.ArrayNode;
import tools.jackson.databind.node.ObjectNode;

import java.io.IOException;
import java.io.InputStream;
import java.io.UncheckedIOException;
import java.util.UUID;
import java.util.function.Consumer;

/**
 * Plan documents generated by Nexora Semantic (see {@code src/test/resources/semantic/README.md}) and helpers to
 * derive tampered or extended variants in memory.
 */
public final class PlanFixtures {

    public static final UUID TENANT = UUID.fromString("f3e391c4-2201-4dff-9e65-8b2766ab54bb");
    public static final UUID DATA_SOURCE = UUID.fromString("40d88cc6-d9c8-4c8b-b08e-c3363683a128");

    public static final String SINGLE_OBJECT = "plan-single-object.json";
    public static final String WEEK = "plan-week.json";
    public static final String INNER_JOIN = "plan-inner-join-composite.json";
    public static final String LEFT_JOIN = "plan-left-join.json";
    public static final String LEFT_JOIN_FILTERS = "plan-left-join-filters.json";
    public static final String IS_NOT_NULL = "plan-is-not-null.json";

    public static final JsonMapper JSON = JsonMapper.builder().build();
    private static final PlanDocumentReader READER = new PlanDocumentReader();

    private PlanFixtures() {
    }

    public static String text(String name) {
        try (InputStream in = PlanFixtures.class.getResourceAsStream("/semantic/" + name)) {
            if (in == null) {
                throw new IllegalArgumentException("missing fixture " + name);
            }
            return new String(in.readAllBytes(), java.nio.charset.StandardCharsets.UTF_8);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    public static ObjectNode tree(String name) {
        return (ObjectNode) JSON.readTree(text(name));
    }

    /** A modified copy of a fixture envelope. */
    public static ObjectNode mutate(String name, Consumer<ObjectNode> change) {
        ObjectNode envelope = tree(name);
        change.accept(envelope);
        return envelope;
    }

    public static StoredPlan read(JsonNode envelope) {
        return READER.plan(JSON.writeValueAsBytes(envelope));
    }

    public static StoredPlan read(String name) {
        return read(tree(name));
    }

    public static UUID planId(JsonNode envelope) {
        return UUID.fromString(envelope.get("id").asString());
    }

    // --- navigation helpers on the "plan" object of an envelope ---

    public static ObjectNode plan(ObjectNode envelope) {
        return (ObjectNode) envelope.get("plan");
    }

    public static ArrayNode array(ObjectNode envelope, String name) {
        return (ArrayNode) plan(envelope).get(name);
    }

    public static ObjectNode element(ObjectNode envelope, String array, int index) {
        return (ObjectNode) array(envelope, array).get(index);
    }

    /** The physical object (or definition) whose field {@code field} equals {@code value}. */
    public static ObjectNode find(ObjectNode envelope, String array, String field, String value) {
        for (JsonNode node : array(envelope, array)) {
            if (node.has(field) && value.equals(node.get(field).asString())) {
                return (ObjectNode) node;
            }
        }
        throw new IllegalArgumentException("no element of " + array + " with " + field + "=" + value);
    }

    public static ObjectNode column(ObjectNode envelope, String naturalKey) {
        return find(envelope, "physicalObjects", "naturalKey", naturalKey);
    }

    public static ObjectNode definition(ObjectNode envelope, String key) {
        return find(envelope, "definitions", "key", key);
    }

    /**
     * Rewrites {@code operations} exactly as Semantic derives them from the joins and filters (used after a test
     * adds or removes filters, so that only the intended difference remains).
     */
    public static void rebuildOperations(ObjectNode envelope) {
        ArrayNode operations = array(envelope, "operations");
        operations.removeAll();
        int order = 1;
        addOperation(operations, order++, "SCAN");
        for (int i = 1; i <= array(envelope, "joins").size(); i++) {
            addOperation(operations, order++, "JOIN", i);
        }
        int pre = array(envelope, "preAggregationFilters").size();
        if (pre > 0) {
            addOperation(operations, order++, "FILTER_ROWS", range(pre));
        }
        addOperation(operations, order++, "GROUP_AND_AGGREGATE");
        int post = array(envelope, "postAggregationFilters").size();
        if (post > 0) {
            addOperation(operations, order, "FILTER_GROUPS", range(post));
        }
    }

    /** Appends a row filter on a dimension of the base object (as Semantic would build it) and fixes operations. */
    public static void addRowFilter(ObjectNode envelope, String dimensionKey, String operator, String valueType,
                                    String... values) {
        ObjectNode definition = definition(envelope, dimensionKey);
        ArrayNode filters = array(envelope, "preAggregationFilters");
        ObjectNode filter = filters.addObject();
        filter.put("order", filters.size());
        filter.put("definitionId", definition.get("id").asString());
        filter.put("definitionKind", "DIMENSION");
        filter.put("operator", operator);
        filter.put("valueType", valueType);
        filter.put("objectId", plan(envelope).get("base").get("objectId").asString());
        filter.put("columnObjectId", definition.get("columnObjectId").asString());
        ArrayNode list = filter.putArray("values");
        for (String value : values) {
            list.add(value);
        }
        rebuildOperations(envelope);
    }

    public static void clearRowFilters(ObjectNode envelope) {
        array(envelope, "preAggregationFilters").removeAll();
        rebuildOperations(envelope);
    }

    public static void clearGroupFilters(ObjectNode envelope) {
        array(envelope, "postAggregationFilters").removeAll();
        rebuildOperations(envelope);
    }

    private static int[] range(int size) {
        int[] values = new int[size];
        for (int i = 0; i < size; i++) {
            values[i] = i + 1;
        }
        return values;
    }

    private static void addOperation(ArrayNode operations, int order, String kind, int... references) {
        ObjectNode operation = operations.addObject();
        operation.put("order", order);
        operation.put("kind", kind);
        ArrayNode refs = operation.putArray("references");
        for (int reference : references) {
            refs.add(reference);
        }
    }

    /** Gives the envelope a new plan id (to register a variant next to the original in fake Semantic). */
    public static UUID renew(ObjectNode envelope) {
        UUID id = UUID.randomUUID();
        envelope.put("id", id.toString());
        return id;
    }
}
